inline const Glyph& glyph(unsigned int codepoint) {
    unsigned int c = codepoint;
    if (c >= 'a' && c <= 'z') c -= 32;
    for (const auto& g : kGlyphs) if (g.code == c) return g;
    return kGlyphs[sizeof(kGlyphs) / sizeof(kGlyphs[0]) - 1];   // box (127 sorts last)
}

